// Simple task processing - extract company data
const tasks = $input.first().json.result || [];
console.log(`Found ${tasks.length} total tasks`);

const results = [];

for (const task of tasks) {
  const title = task.title || '';
  const description = task.description || '';

  // Look for company tasks (you can modify this filter)
  if (title.toLowerCase().includes('due diligence') || 
      title.toLowerCase().includes('company') ||
      description.toLowerCase().includes('website')) {

    // Extract company name from title
    let companyName = title.replace(/due diligence:\s*/i, '').trim();
    if (!companyName) companyName = title.trim();

    // Extract website from description
    const websiteMatch = description.match(/(?:website|url|site)\s*:?\s*(https?:\/\/[^\s]+|www\.[^\s]+|[a-zA-Z0-9.-]+\.[a-zA-Z]{2,})/i);
    const website = websiteMatch ? websiteMatch[1] : '';

    results.push({
      task_id: parseInt(task.id),
      company_name: companyName,
      website: website,
      description: description
    });

    console.log(`Found company task: ${companyName} (ID: ${task.id})`);
  }
}

if (results.length === 0) {
  console.log('No company tasks found');
  return [];
}

console.log(`Processing ${results.length} company tasks`);
return results.map(item => ({ json: item }));

// Check if task has PDF files
const taskData = $input.first().json;
const filesData = $input.last().json;

const files = filesData.result || [];
console.log(`Task ${taskData.task_id}: Found ${files.length} total files`);

// Debug: Log all files found
files.forEach(file => {
  console.log(`File found: ${file.name} (size: ${file.size}, type: ${file.mimetype || 'unknown'})`);
});

// Look for PDF files with better filtering
const pdfFiles = files.filter(file => {
  if (!file.name) return false;

  const fileName = file.name.toLowerCase();
  const isPDF = fileName.endsWith('.pdf');
  const isPDFMimetype = file.mimetype && file.mimetype.includes('pdf');

  console.log(`File ${file.name}: isPDF=${isPDF}, mimetype=${file.mimetype}`);

  return isPDF || isPDFMimetype;
});

console.log(`Found ${pdfFiles.length} PDF files out of ${files.length} total files`);

if (pdfFiles.length === 0) {
  console.log(`No PDF files found for task ${taskData.task_id}`);
  // Return task data without PDF processing
  return {
    json: {
      ...taskData,
      pdf_text: 'No PDF file attached',
      has_pdf: false
    }
  };
}

// Process first PDF file
const pdfFile = pdfFiles[0];
console.log(`Processing PDF: ${pdfFile.name} (ID: ${pdfFile.id})`);

// Kanboard file download URL format
const downloadUrl = `/index.php?controller=FileController&action=download&file_id=${pdfFile.id}&token=${pdfFile.token}`;
console.log(`Download URL: ${downloadUrl}`);

return {
  json: {
    ...taskData,
    file_id: pdfFile.id,
    file_name: pdfFile.name,
    file_size: pdfFile.size,
    file_mimetype: pdfFile.mimetype,
    file_path: downloadUrl,
    has_pdf: true
  }
};

// Validate PDF file before extraction
const item = $input.first();
const binaryData = item.binary;

console.log('Binary data keys:', Object.keys(binaryData || {}));

if (!binaryData || !binaryData.data) {
  throw new Error('No binary data found in downloaded file');
}

const fileName = binaryData.data.fileName || 'unknown';
const mimeType = binaryData.data.mimeType || 'unknown';
const fileSize = binaryData.data.fileSize || 0;

console.log(`Downloaded file: ${fileName}`);
console.log(`MIME type: ${mimeType}`);
console.log(`File size: ${fileSize} bytes`);

// Check if it's actually a PDF
if (!mimeType.includes('pdf') && !fileName.toLowerCase().endsWith('.pdf')) {
  throw new Error(`File is not a PDF. MIME type: ${mimeType}, filename: ${fileName}`);
}

// Check file size
if (fileSize === 0) {
  throw new Error('Downloaded file is empty');
}

console.log('✅ PDF validation passed, proceeding to extract text');

// Return the item as-is for PDF extraction
return item;

// Combine PDF text with task data
// Handle both paths: with PDF extraction and without PDF
const inputs = $input.all();
console.log(`Combine Data: Received ${inputs.length} inputs`);

// Check if we have PDF text data
let taskData, pdfText = 'No PDF file attached';

if (inputs.length === 1) {
  // Single input - either from 'no PDF' path or from PDF extraction
  const input = inputs[0].json;

  if (input.data) {
    // This is from PDF extraction
    pdfText = input.data;
    // Get task data from original context (need to get from previous nodes)
    taskData = {
      task_id: $('Has PDF File?').first().json.task_id,
      company_name: $('Has PDF File?').first().json.company_name,
      website: $('Has PDF File?').first().json.website,
      file_name: $('Has PDF File?').first().json.file_name
    };
  } else {
    // This is from 'no PDF' path
    taskData = input;
    pdfText = input.pdf_text || 'No PDF file attached';
  }
} else if (inputs.length === 2) {
  // Two inputs - task data and PDF data
  taskData = inputs[0].json;
  pdfText = inputs[1].json.data || 'Could not extract PDF text';
}

console.log(`Final data: Task ${taskData.task_id}, Company: ${taskData.company_name}`);
console.log(`PDF text length: ${pdfText.length} characters`);

return {
  json: {
    task_id: taskData.task_id,
    company_name: taskData.company_name,
    website: taskData.website,
    pdf_text: pdfText,
    file_name: taskData.file_name || 'N/A'
  }
};
